CREATE TABLE public.vault_claims (
    id text NOT NULL,
    space_id text NOT NULL,
    statement text NOT NULL,
    slot_key text,
    value jsonb,
    kind text DEFAULT 'fact'::text NOT NULL,
    origin jsonb NOT NULL,
    review_status text DEFAULT 'unverified'::text NOT NULL,
    sensitive boolean DEFAULT false NOT NULL,
    valid_from timestamp without time zone,
    valid_to timestamp without time zone,
    recorded_at timestamp without time zone DEFAULT now() NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    supersedes text,
    superseded_at timestamp without time zone,
    approved_at timestamp without time zone,
    approved_by_user_id text,
    source_class text NOT NULL,
    prompt_access text GENERATED ALWAYS AS (
CASE
    WHEN sensitive THEN 'owner_only'::text
    WHEN (source_class = ANY (ARRAY['legacy_confirmed'::text, 'owner_authored'::text, 'user_direct'::text])) THEN 'manifest'::text
    WHEN (source_class = 'agent_inferred'::text) THEN 'memory_search'::text
    ELSE 'knowledge_search'::text
END) STORED NOT NULL,
    conflicts_with text,
    normalized_hash text,
    created_task_id text,
    expires_at timestamp without time zone,
    retired_at timestamp without time zone,
    last_used_at timestamp without time zone,
    CONSTRAINT ck_vault_claims_source_class CHECK ((source_class = ANY (ARRAY['legacy_confirmed'::text, 'owner_authored'::text, 'user_direct'::text, 'agent_inferred'::text, 'untrusted_derived'::text])))
);

