    CONSTRAINT ck_vnote_versions_source_class CHECK ((source_class = ANY (ARRAY['legacy_confirmed'::text, 'owner_authored'::text, 'user_direct'::text, 'agent_inferred'::text, 'untrusted_derived'::text])))
