CREATE TABLE public.vault_search_documents (
    id text NOT NULL,
    space_id text NOT NULL,
    node_id text NOT NULL,
    fragment_id text DEFAULT ''::text NOT NULL,
    kind text NOT NULL,
    title text DEFAULT ''::text NOT NULL,
    owner_text text NOT NULL,
    model_text text,
    norm_title text GENERATED ALWAYS AS (lower(btrim(regexp_replace(COALESCE(title, ''::text), '[[:space:]\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]+'::text, ' '::text, 'g'::text)))) STORED NOT NULL,
    norm_owner_text text GENERATED ALWAYS AS (lower(btrim(regexp_replace(COALESCE(owner_text, ''::text), '[[:space:]\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]+'::text, ' '::text, 'g'::text)))) STORED NOT NULL,
    norm_model_text text GENERATED ALWAYS AS (lower(btrim(regexp_replace(model_text, '[[:space:]\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]+'::text, ' '::text, 'g'::text)))) STORED,
    owner_tsv tsvector GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, ((title || ' '::text) || owner_text))) STORED,
    model_tsv tsvector GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, ((title || ' '::text) || COALESCE(model_text, ''::text)))) STORED,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_vsearch_kind CHECK ((kind = ANY (ARRAY['claim'::text, 'note'::text, 'source'::text, 'fragment'::text])))
);

